import { useEffect, useState } from "react";
import { listBanners } from "./api/banners";
import { getUserCountry, getNow } from "./user";

// 국가와 기간이 맞는 예약 중 등록일이 가장 늦은 배너를 고른다.
export function pickBanner(banners, country, now) {
  const matched = banners.filter((b) => {
    if (!b.country) return false;
    if (b.country !== country) return false;
    const start = new Date(b.startAt);
    const end = new Date(b.endAt);
    return start <= now && now < end;
  });
  if (matched.length === 0) return banners.find((b) => !b.country) ?? null;
  return matched.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt))[0];
}

export default function Home() {
  const [banners, setBanners] = useState([]);
  const country = getUserCountry();
  useEffect(() => { listBanners().then(setBanners); }, []);
  const banner = pickBanner(banners, country, getNow());
  return (
    <section className="home">
      <div className="slot">
        {banner ? <img src={banner.imageUrl} alt={banner.title} /> : <div className="empty">배너 없음</div>}
      </div>
      <p className="hint">현재 사용자 국가: {country}</p>
    </section>
  );
}
